using Asp.Versioning;using CashFlow.Launch.Api.Dtos.Requests;using CashFlow.Launch.Domain.Interfaces.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace CashFlow.Launch.Api.Controllers;
[ApiController][ApiVersion("1.0")][Route("api/v{version:apiVersion}/accounts")][Authorize]public class AccountsController:ControllerBase{private readonly IAccountService _service;public AccountsController(IAccountService service)=>_service=service;[HttpPost]public async Task<IActionResult>Create(CreateAccountRequest r){if(string.IsNullOrWhiteSpace(r.Name))return BadRequest("Account name is required.");return Ok(await _service.CreateAsync(r.Name,r.Type,r.InitialBalance));}[HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,CreateAccountRequest r){if(string.IsNullOrWhiteSpace(r.Name))return BadRequest("Account name is required.");var x=await _service.UpdateAsync(id,r.Name,r.Type,r.InitialBalance);return x is null?NotFound():Ok(x);}[HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id)=>await _service.DeleteAsync(id)?NoContent():NotFound();[HttpGet]public async Task<IActionResult>GetAll()=>Ok(await _service.GetAllAsync());[HttpGet("{id:guid}")]public async Task<IActionResult>GetById(Guid id){var x=await _service.GetByIdAsync(id);return x is null?NotFound():Ok(x);}}
